/**
 * 负责固定已提交 Git 字节的结构检查，输入为公开源码、同提交文档和原冻结债务；输出为报告。
 * 不读并行产品 WIP，不修改债务、私有配置或历史来源；运行时工具必须仍为该提交同字节。
 * 仅覆盖依赖、包、命名及职责形状，行为、全部中文内容与同源全量验收仍需另证。
 */
import fs from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {readPublicGitBlobs} from '/home/hby/dev/AI-Werewolf-Arena/tooling/refactor/inventory';
import {checkArchitecture} from '/home/hby/dev/AI-Werewolf-Arena/tooling/refactor/architecture/run';
const repository='/home/hby/dev/AI-Werewolf-Arena',commit='37f56392322fdfa859b0d674f339693e0ca883ff';
const hash=(s:Uint8Array|string)=>createHash('sha256').update(s).digest('hex');
const blobs=readPublicGitBlobs(repository,commit);
const files=blobs.files.map(({path,bytes})=>({path,text:bytes.toString('utf8'),sha256:hash(bytes)}));
const documentationPaths=execFileSync('git',['ls-tree','-r','--name-only',commit],{cwd:repository,encoding:'utf8'}).trim().split('\n').filter(p=>/^docs\/.*\.md$/.test(p)||p==='README.md').sort();
const debtBytes=execFileSync('git',['show',commit+':docs/refactor/generated/architecture-debt.json'],{cwd:repository,maxBuffer:32*1024*1024});
const debt=JSON.parse(debtBytes.toString('utf8'));
const report=checkArchitecture(repository,{files,documentationPaths},debt);
const capture={commit,files:files.map(({path,sha256})=>({path,sha256})),documentationPaths,debtSha256:hash(debtBytes),gateModules:['tooling/refactor/architecture/run.ts','tooling/refactor/architecture/contracts.ts','tooling/refactor/architecture/dependency-check.ts','tooling/refactor/architecture/comment-check.ts','tooling/refactor/architecture/naming-check.ts'].map(path=>{const git=execFileSync('git',['show',commit+':'+path],{cwd:repository});const current=fs.readFileSync(repository+'/'+path);if(!git.equals(current))throw Error('checkpoint_gate_source_changed');return{path,sha256:hash(git)};}),report};
fs.writeFileSync(repository+'/docs/refactor/generated/architecture-checkpoint-37f56392.json',JSON.stringify(capture,null,2)+'\n');
console.log(JSON.stringify({commit,files:files.length,documentationPaths:documentationPaths.length,debtSha256:capture.debtSha256,counts:report.counts,failures:report.failures}));if(report.failures.length)process.exitCode=1;
